final_verifications.command:
$probeSource = @'
import { buildLearningDataset } from "./src/learning-evidence/dataset.ts";
const base = { horizon: "15m", asOfMs: 900000 };
const observations = [];
for (const field of ["minTrainGroups","testGroups","embargoMs"]) {
  try {
    const result = buildLearningDataset([], [], { ...base, [field]: null });
    observations.push({field,value:null,result:"accepted",settings:result.settings});
  } catch(error) {
    observations.push({field,value:null,result:"rejected",error:error instanceof Error ? error.message : "unknown"});
  }
}
for (const options of [base,{...base,minTrainGroups:undefined,testGroups:undefined,embargoMs:undefined}]) {
  const result = buildLearningDataset([], [], options);
  observations.push({kind:options===base?"omitted":"undefined",result:"accepted",settings:result.settings});
}
console.log(JSON.stringify(observations));
if (observations.slice(0,3).some(x => x.result!=="rejected" || x.error!=="invalid_options")) throw new Error("null_validation_failed");
if (observations.slice(3).some(x => JSON.stringify(x.settings)!==JSON.stringify({minTrainGroups:30,testGroups:12,embargoMs:0}))) throw new Error("defaults_changed");
'@
bun --no-env-file --eval $probeSource
